styles:
body { margin: 0; }
    a { color: #6b521f; text-decoration: underline; text-decoration-color: rgba(138,109,59,0.35); }
    a:hover { color: #5c4826; }
    ::selection { background: rgba(138,109,59,0.25); }

logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "1982-bolivar",
      label: "Doscientos Pesos Oro \u00b7 1 de enero de 1982 \u00b7 Bolívar",
      denomination: "Doscientos Pesos Oro",
      date: "1 de enero de 1982",
      obverse: "Multicolor, predomina el verde y el negro. Retrato de Simón Bolívar a la derecha con fondo arquitectónico. Leyenda: \u201cEL BANCO DE LA REPÚBLICA PAGARÁ AL PORTADOR DOSCIENTOS PESOS ORO\u201d. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d. Numeración en ceros. Firmas de Gerente y Secretario. Bogotá, 1 de enero de 1982.",
      reverse: "Multicolor. Viñeta central de una recolectora de café junto a arbustos y granos de la cosecha. Escudo de Colombia y medallón de la Libertad. Texto: \u201cDOSCIENTOS PESOS ORO\u201d. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Espécimen sin circular, con perforaciones de cancelación características y numeración en ceros.",
      rarity: "Espécimen atractivo de los años 1980 que combina un héroe nacional con la cultura cafetera colombiana.",
      description: "Espécimen de transición, con el último uso del retrato de Bolívar en esta denominación y un homenaje explícito a la industria cafetera en el reverso.",
      jpg: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1982-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1982-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1982-specimen-640.webp",
      alt: "Billete especimen de Doscientos Pesos Oro de El Banco de la República, Colombia, fechado 1 de enero de 1982, anverso con el retrato de Simón Bolívar y reverso con una recolectora de café"
    },
    {
      key: "1983-mutis",
      label: "Doscientos Pesos Oro \u00b7 1 de abril de 1983 \u00b7 Mutis",
      denomination: "Doscientos Pesos Oro",
      date: "1 de abril de 1983",
      obverse: "Multicolor, predomina el verde. Retrato de José Celestino Mutis a la izquierda, con el Claustro de Nuestra Señora del Rosario al fondo. Sobreimpresión roja \u201cSPECIMEN\u201d e inscripción \u201cSPECIMEN N.\u00b0 723\u201d. Numeración en ceros (000000000). Bogotá, 1 de abril de 1983.",
      reverse: "Multicolor. Viñeta del Claustro Mayor de Nuestra Señora del Rosario, con el escudo de Colombia y el medallón de la Libertad. Texto: \u201cDOSCIENTOS PESOS ORO\u201d. Sobreimpresión roja \u201cSPECIMEN\u201d.",
      condition: "Espécimen sin circular, con perforaciones de cancelación características y numeración en ceros.",
      rarity: "Primer año del diseño con Mutis y el Claustro del Rosario; marcado énfasis cultural y arquitectónico.",
      description: "Espécimen que introduce el diseño con José Celestino Mutis, vigente durante casi una década, todavía con la sobreimpresión en inglés \u201cSPECIMEN\u201d propia de la época.",
      jpg: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1983-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1983-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1983-specimen-640.webp",
      alt: "Billete especimen de Doscientos Pesos Oro de El Banco de la República, Colombia, fechado 1 de abril de 1983, anverso con el retrato de José Celestino Mutis y reverso con el Claustro de Nuestra Señora del Rosario"
    },
    {
      key: "1992-mutis",
      label: "Doscientos Pesos Oro \u00b7 10 de agosto de 1992 \u00b7 Mutis",
      denomination: "Doscientos Pesos Oro",
      date: "10 de agosto de 1992",
      obverse: "Multicolor, predomina el verde. Retrato de José Celestino Mutis a la izquierda, con el Claustro de Nuestra Señora del Rosario al fondo. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d. Numeración en ceros (00000000). Santa Fe de Bogotá, 10 de agosto de 1992.",
      reverse: "Multicolor. Viñeta detallada del Claustro Mayor de Nuestra Señora del Rosario con documentos y el escudo de Colombia. Texto: \u201cDOSCIENTOS PESOS ORO\u201d. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Espécimen sin circular, con perforaciones de cancelación características y numeración en ceros.",
      rarity: "Ejemplar tardío de 1992 que documenta el mismo diseño una década después, con la denominación de la ciudad ya como \u201cSanta Fe de Bogotá\u201d.",
      description: "Espécimen de la última etapa de este diseño, prácticamente idéntico al de 1983 salvo por la fecha y la sobreimpresión ya castellanizada.",
      jpg: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1992-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1992-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-200-pesos-oro-1992-specimen-640.webp",
      alt: "Billete especimen de Doscientos Pesos Oro de El Banco de la República, Colombia, fechado 10 de agosto de 1992, anverso con el retrato de José Celestino Mutis y reverso con el Claustro de Nuestra Señora del Rosario"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
